const photo=(id)=>Catalog.escape(Catalog.image(id));
let products=Catalog.list().filter(p=>p.active);
const esc=Catalog.escape;

const $=(s)=>document.querySelector(s),money=(v)=>new Intl.NumberFormat('uz-UZ').format(v).replaceAll(',', ' ');
function read(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value??fallback}catch{return fallback}}
let cart=read('birga-cart',{}),wish=read('birga-wish',[]);if(!cart||Array.isArray(cart)||typeof cart!=='object')cart={};if(!Array.isArray(wish))wish=[];wish=wish.filter(id=>products.some(p=>p.id===id));for(const id of Object.keys(cart))if(!products.some(p=>p.id===Number(id))||!Number.isInteger(cart[id])||cart[id]<1)delete cart[id];
for(const id of Object.keys(cart)){const p=products.find(p=>p.id===Number(id));if(!p||!p.stock)delete cart[id];else cart[id]=Math.min(cart[id],p.stock)}
let category='all',query='',favoritesOnly=false,saleOnly=false,limit=10,toastTimer;
function save(){try{localStorage.setItem('birga-cart',JSON.stringify(cart));localStorage.setItem('birga-wish',JSON.stringify(wish))}catch{} updateCounts()}
function updateCounts(){const count=Object.values(cart).reduce((a,b)=>a+b,0);$('#cart-count').textContent=count;$('#cart-count').hidden=!count;$('#wish-count').textContent=wish.length;$('#wish-count').hidden=!wish.length;$('#favorites').style.color=favoritesOnly?'var(--orange)':''}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function filtered(){let list=products.filter(p=>(category==='all'||p.cat===category)&&(!favoritesOnly||wish.includes(p.id))&&(!saleOnly||p.old>p.price)&&(!query||(p.name+' '+p.cat).toLocaleLowerCase().includes(query.toLocaleLowerCase())));const sort=$('#sort').value;if(sort==='cheap')list.sort((a,b)=>a.price-b.price);if(sort==='expensive')list.sort((a,b)=>b.price-a.price);if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);return list}
function render(){const list=filtered();$('#section-title').textContent=favoritesOnly?'Saralangan mahsulotlar':query?'Qidiruv natijalari':saleOnly?'Chegirmadagi mahsulotlar':category==='all'?'Bugunning topilmalari':category;$('#result-count').textContent=`${list.length} ta mahsulot`;$('#products').innerHTML=list.length?list.slice(0,limit).map(p=>`<article class="product"><div class="product-image"><button data-detail="${p.id}" aria-label="${esc(p.name)} tafsilotlari"><img src="${photo(p.img)}" alt="${esc(p.name)}" loading="lazy"></button><span class="badge ${p.badge.startsWith('−')?'orange':''}">${esc(p.badge)}</span><button class="wish ${wish.includes(p.id)?'on':''}" data-wish="${p.id}" aria-label="${wish.includes(p.id)?'Saralanganlardan o‘chirish':'Saralanganlarga qo‘shish'}" aria-pressed="${wish.includes(p.id)}">${wish.includes(p.id)?'♥':'♡'}</button></div><div class="rating"><strong>★ ${p.rating}</strong> (${p.reviews} ta sharh)</div><button class="product-title" data-detail="${p.id}">${esc(p.name)}</button><div class="product-bottom"><div><div class="price">${money(p.price)} <small>so‘m</small></div><span class="old-price">${money(p.old)} so‘m</span><div class="installment">${money(Math.ceil(p.price/12))} so‘m × 12 oy*</div></div><button class="add-cart" ${p.stock===0?'disabled':''} data-add="${p.id}" aria-label="${esc(p.name)} savatga qo‘shish">+</button></div><div class="delivery">Demo katalog mahsuloti</div></article>`).join(''):'<div class="empty"><b>Hozircha mahsulot yo‘q</b>Qidiruvni o‘zgartiring yoki boshqa kategoriyani tanlang.</div>';$('#show-more').hidden=limit>=list.length;document.querySelectorAll('[data-cat]').forEach(b=>{const on=b.dataset.cat===category;b.classList.toggle(b.closest('.categories')?'active':'selected',on)});updateCounts()}
function selectCategory(cat){category=cat;query='';$('#search').value='';favoritesOnly=false;saleOnly=false;limit=10;render();$('#products-section').scrollIntoView({behavior:'smooth',block:'start'})}
function add(id){const p=products.find(p=>p.id===id);if(!p||p.stock<=(cart[id]||0)){toast('Omborda yetarli mahsulot yo'+String.fromCharCode(0x2018)+'q');return}cart[id]=(cart[id]||0)+1;save();toast('Mahsulot savatga qo‘shildi');if(!$('#drawer').hidden)renderCart()}
function showInfo(title,body){$('#modal-content').innerHTML=`<h2>${title}</h2><div class="info-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function detail(id){const p=products.find(x=>x.id===id);$('#modal-content').innerHTML=`<div class="detail"><img src="${photo(p.img)}" alt="${esc(p.name)}"><div><div class="eyebrow">${esc(p.cat)}</div><h2>${esc(p.name)}</h2><p>★ ${p.rating} · ${p.reviews} ta namunaviy sharh</p><p>${esc(p.desc)}</p><div class="detail-price">${money(p.price)} so‘m</div><p class="note">Narxlar va mahsulotlar namoyish uchun berilgan. *Bo‘lib to‘lash summasi taxminiy hisob.</p><button class="dark-button" data-add="${p.id}">Savatga qo‘shish +</button></div></div>`;$('#modal').showModal()}
function renderCart(){let total=0,count=0;$('#cart-items').innerHTML=Object.entries(cart).map(([id,qty])=>{const p=products.find(x=>x.id===+id);total+=p.price*qty;count+=qty;return `<div class="cart-item"><img src="${photo(p.img)}" alt="${esc(p.name)}"><div><p>${esc(p.name)}</p><b>${money(p.price*qty)} so‘m</b><div class="quantity"><button data-qty="${id}" data-delta="-1" aria-label="Sonini kamaytirish">−</button><span>${qty}</span><button data-qty="${id}" data-delta="1" aria-label="Sonini oshirish">+</button><button class="remove" data-remove="${id}">O‘chirish</button></div></div></div>`}).join('')||'<div class="empty"><b>Savatingiz hozircha bo‘sh</b>Yaxshi topilmalarni shu yerga yig‘ing.</div>';$('#cart-total').innerHTML=count?`<p><span>Mahsulotlar (${count} ta)</span><b>${money(total)} so‘m</b></p><p class="note">Yetkazib berish narxi hisoblanmagan. Bu namoyish talqini, haqiqiy to‘lov olinmaydi.</p><button class="dark-button" id="checkout">Buyurtmani ko‘rib chiqish ↗</button>`:''}
function openCart(){$('#overlay').hidden=false;$('#drawer').hidden=false;document.body.style.overflow='hidden';renderCart();$('#drawer .close').focus()}
function closeCart(){$('#overlay').hidden=true;$('#drawer').hidden=true;document.body.style.overflow='';$('#cart').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.cat)selectCategory(b.dataset.cat);if(b.dataset.add)add(+b.dataset.add);if(b.dataset.detail)detail(+b.dataset.detail);if(b.dataset.wish){const id=+b.dataset.wish;wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];save();render()}if(b.dataset.qty){const id=b.dataset.qty;const p=products.find(p=>p.id===Number(id));if(Number(b.dataset.delta)>0&&(!p||cart[id]>=p.stock)){toast('Ombor chegarasiga yetdingiz');return}cart[id]+=Number(b.dataset.delta);if(cart[id]<=0)delete cart[id];save();renderCart()}if(b.dataset.remove){delete cart[b.dataset.remove];save();renderCart()}if(b.id==='checkout'){const count=Object.values(cart).reduce((a,b)=>a+b,0);closeCart();showInfo('Buyurtmangiz tayyor',`<p>Savatingizda ${count} ta mahsulot bor. Tanlovingiz ushbu brauzerda saqlanadi.</p><p><b>Bu namoyish sayti.</b> Haqiqiy buyurtma yuborilmadi va to‘lov olinmaydi. Buyurtma qabul qilish, ombor va to‘lov integratsiyasi hali ulanmagan.</p>`)} });
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query=$('#search').value.trim();category='all';favoritesOnly=false;saleOnly=false;limit=10;render();$('#products-section').scrollIntoView({behavior:'smooth'})});
$('#search').addEventListener('input',()=>{query=$('#search').value.trim();category='all';favoritesOnly=false;limit=10;render()});$('#sort').addEventListener('change',render);$('#show-more').onclick=()=>{limit+=10;render()};$('#hero-shop').onclick=()=>selectCategory('all');$('#cart').onclick=openCart;$('#overlay').onclick=closeCart;$('#drawer .close').onclick=closeCart;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#drawer').hidden)closeCart();if(e.key==='Tab'&&!$('#drawer').hidden){const focusables=[...$('#drawer').querySelectorAll('button')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('#modal>.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function showFavorites(){favoritesOnly=!favoritesOnly;category='all';query='';$('#search').value='';saleOnly=false;limit=20;render();$('#products-section').scrollIntoView({behavior:'smooth'})}$('#favorites').onclick=showFavorites;$('#bottom-favorites').onclick=showFavorites;
$('#sale-nav').onclick=()=>{category='all';favoritesOnly=false;query='';$('#search').value='';saleOnly=true;limit=20;render();$('#products-section').scrollIntoView({behavior:'smooth'})};
$('#catalog').onclick=()=>showInfo('Katalog',`<div class="city-list">${['all','Elektronika','Kiyimlar','Uy va ro‘zg‘or','Go‘zallik','Sport','Bolalar'].map(cat=>`<button data-catalog-cat="${cat}">${cat==='all'?'Barcha mahsulotlar':cat} ↗</button>`).join('')}</div>`);
$('#location').onclick=()=>showInfo('Shahringizni tanlang','<p class="note">Shahar tanlovi ushbu brauzerda saqlanadi. Yetkazib berish xizmati hali ulanmagan.</p><div class="city-list">'+['Toshkent','Samarqand','Buxoro','Andijon','Namangan','Farg‘ona','Nukus'].map(city=>`<button data-city="${city}">⌖ ${city}</button>`).join('')+'</div>');
$('#modal').addEventListener('click',e=>{const cat=e.target.closest('[data-catalog-cat]');if(cat){$('#modal').close();selectCategory(cat.dataset.catalogCat)}const city=e.target.closest('[data-city]');if(city){$('#location span').textContent=city.dataset.city;try{localStorage.setItem('birga-city',city.dataset.city)}catch{}$('#modal').close();toast('Shahar tanlandi')}});
let city;try{city=localStorage.getItem('birga-city')}catch{}if(city)$('#location span').textContent=city;
const help=()=>showInfo('Sizga yordam beramiz',`<p>Mahsulotlarni qidiring, kategoriyalar orqali tanlang va savatga qo‘shing. ♡ belgisi yoqqan mahsulotingizni saqlaydi.</p><p>Savatda mahsulot sonini o‘zgartirish va jami summani ko‘rish mumkin.</p><p>Bu marketplace prototipi: haqiqiy sotuv, yetkazib berish, bo‘lib to‘lash va mijozlarni qo‘llab-quvvatlash xizmati hali ishga tushmagan. Katalogdagi narxlar va sharhlar namunaviy.</p>`);$('#help').onclick=help;$('#footer-help').onclick=help;$('#seller').onclick=()=>showInfo('Biznesingizni BIRGA o‘stiring',`<p>BIRGA — mahalliy sotuvchilar va xaridorlarni bir joyda uchrashtiradigan marketplace g‘oyasi.</p><p>Sotuvchi kabineti, mahsulot yuklash, ombor hisobi va buyurtmalar boshqaruvi keyingi bosqichda qo‘shiladi. Hozircha ro‘yxatdan o‘tish ochilmagan.</p>`);
render();

window.addEventListener("storage",e=>{if(e.key===Catalog.key){products=Catalog.list().filter(p=>p.active);for(const id of Object.keys(cart)){const p=products.find(p=>p.id===Number(id));if(!p||!p.stock)delete cart[id];else cart[id]=Math.min(cart[id],p.stock)}save();render();if(!$("#drawer").hidden)renderCart();if($("#modal").open)$("#modal").close()}});
